def snapshot_existing_published_content(apps, schema_editor):
    SiteContent = apps.get_model("cms", "SiteContent")
    Page = apps.get_model("cms", "Page")
    Snapshot = apps.get_model("cms", "PublishedContentSnapshot")
    using = schema_editor.connection.alias
    for content in SiteContent.objects.using(using).filter(status="PUBLISHED").iterator():
        payload = {
            "content_id": str(content.pk),
            "content_type": "cms.sitecontent",
            "site_id": content.site_id,
            "status": "PUBLISHED",
            "locale": content.locale,
            "blocks": content.blocks,
            "blocks_version": content.blocks_version,
            "metadata": content.metadata,
        }
        page = Page.objects.using(using).filter(pk=content.pk).first()
        if page is not None:
            payload.update({
                "content_type": "cms.page",
                "title": page.title,
                "slug": page.slug,
                "path": page.path,
                "layout": page.layout,
                "seo": page.seo,
                "visibility": page.visibility,
                "position": page.position,
                "is_homepage": page.is_homepage,
                "parent_id": page.parent_id,
            })
        Snapshot.objects.using(using).get_or_create(
            content_id=content.pk,
            version=1,
            defaults={
                "payload": payload,
                "published_at": content.published_at or django.utils.timezone.now(),
            },
        )


